def route_request(mode, network_partitioned, has_latest_copy):
    if mode == "CP":
        if network_partitioned and not has_latest_copy:
            return "rechazado: no se puede garantizar consistencia"
        return "ok: dato consistente"
    if mode == "AP":
        return "ok: dato posiblemente desactualizado"
    raise ValueError("modo desconocido")

scenarios = [
    ("CP", False, True),
    ("CP", True, False),
    ("AP", True, False),
]

for mode, partitioned, has_latest in scenarios:
    resultado = route_request(mode, partitioned, has_latest)
    print(f"modo={mode} particion={partitioned} -> {resultado}")
